/* Public examples stay useful without JavaScript; enhancement never edits a scene. */
(() => {
 const search=document.querySelector('[data-search-input]'),category=document.querySelector('[data-category-filter]'),environment=document.querySelector('[data-environment-filter]'),cards=[...document.querySelectorAll('[data-example]')];
 function filter(){let count=0;const words=search.value.toLowerCase().trim().split(/\s+/).filter(Boolean);for(const card of cards){card.hidden=!(category.value==='all'||category.value===card.dataset.category)||(environment&&environment.value!=='all'&&environment.value!==card.dataset.environment)||!words.every(w=>card.dataset.search.includes(w));if(!card.hidden)count++;else card.querySelector('video')?.pause();}document.querySelector('[data-count]').textContent=count+(environment?' creation':' example')+(count===1?'':'s');document.querySelector('[data-empty]').hidden=count!==0;}
 if(search){search.addEventListener('input',filter);category.addEventListener('change',filter);environment?.addEventListener('change',filter);}
 for(const button of document.querySelectorAll('[data-copy]'))button.addEventListener('click',async()=>{const source=document.getElementById(button.dataset.copy),status=document.querySelector('[data-copy-status]');try{await navigator.clipboard.writeText(source.textContent);status.textContent='Prompt copied. Paste it into your connected assistant.';}catch{const selection=getSelection(),range=document.createRange();range.selectNodeContents(source);selection.removeAllRanges();selection.addRange(range);status.textContent='Select and copy the prompt above. Clipboard access is unavailable.';}});
 for(const video of document.querySelectorAll('video'))video.addEventListener('play',()=>{for(const other of document.querySelectorAll('video'))if(other!==video)other.pause();});
})();
